export function resolvedMode(settings,media=()=>false){return settings.theme==='night'||settings.theme==='system'&&media('(prefers-color-scheme: dark)')?'dark':'light';}
export function themeTokens(pack,mode){return (themePacks[pack]||themePacks.graphite)[mode==='dark'?'dark':'light'];}
export function applyTheme(settings,root,mode){const id=Object.hasOwn(themePacks,settings.themePack)?settings.themePack:'graphite',t=themeTokens(id,mode);root.dataset.pack=id;root.dataset.theme=mode;root.style.colorScheme=mode;root.style.backgroundColor=t.paper;root.style.color=t.ink;try{globalThis.localStorage?.setItem('bookwiz-appearance',JSON.stringify({background:t.paper,ink:t.ink,mode}));}catch{}for(const[k,v]of Object.entries(t))root.style.setProperty('--'+k.replace(/[A-Z]/g,m=>'-'+m.toLowerCase()),v);for(const[k,v]of Object.entries({green:t.accent,sage:t.soft,'primary-text':t.accentText,'nav-active':t.soft,'nav-active-text':t.softText,'text':t.ink,'border':t.line,'chrome':t.white,'focus':t.accent}))root.style.setProperty('--'+k,v);root.ownerDocument?.querySelector('meta[name="theme-color"]')?.setAttribute('content',t.paper);globalThis.window?.BookWizHost?.setTheme?.({background:t.paper,dark:mode==='dark'});return t;}
